   135	function removeWaypoint(transaction: OnyxEntry<Transaction>, currentIndex: string, isDraft?: boolean): Promise<void | void[]> {
   136	    // Index comes from the route params and is a string
   137	    const index = Number(currentIndex);
   138	    const existingWaypoints = transaction?.comment?.waypoints ?? {};
   139	    const totalWaypoints = Object.keys(existingWaypoints).length;
   140	
   141	    const waypointValues = Object.values(existingWaypoints);
   142	    const removed = waypointValues.splice(index, 1);
   143	    if (removed.length === 0) {
   144	        return Promise.resolve();
   145	    }
   146	
   147	    const isRemovedWaypointEmpty = removed.length > 0 && !TransactionUtils.waypointHasValidAddress(removed[0] ?? {});
   148	
   149	    // When there are only two waypoints we are adding empty waypoint back
   150	    if (totalWaypoints === 2 && (index === 0 || index === totalWaypoints - 1)) {
   151	        waypointValues.splice(index, 0, {});
   152	    }
   153	
   154	    const reIndexedWaypoints: WaypointCollection = {};
   155	    waypointValues.forEach((waypoint, idx) => {
   156	        reIndexedWaypoints[`waypoint${idx}`] = waypoint;
   157	    });
   158	
   159	    // Onyx.merge won't remove the null nested object values, this is a workaround
   160	    // to remove nested keys while also preserving other object keys
   161	    // Doing a deep clone of the transaction to avoid mutating the original object and running into a cache issue when using Onyx.set
   162	    let newTransaction: Transaction = {
   163	        // eslint-disable-next-line @typescript-eslint/non-nullable-type-assertion-style
   164	        ...(transaction as Transaction),
   165	        comment: {
   166	            ...transaction?.comment,
   167	            waypoints: reIndexedWaypoints,
   168	        },
   169	        // We want to reset the amount only for draft transactions (when creating the expense).
   170	        // When modifying an existing transaction, the amount will be updated on the actual IOU update operation.
   171	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
   172	    };
   173	
   174	    if (!isRemovedWaypointEmpty) {
   175	        newTransaction = {
   176	            ...newTransaction,
   177	            // Clear any errors that may be present, which apply to the old route
   178	            errorFields: {
   179	                route: null,
   180	            },
   181	            // Clear the existing route so that we don't show an old route
   182	            routes: {
   183	                route0: {
   184	                    // Clear the existing distance to recalculate next time
   185	                    distance: null,
   186	                    geometry: {
   187	                        coordinates: null,
   188	                    },
   189	                },
   190	            },
   191	        };
   192	    }
   193	    if (isDraft) {
   194	        return Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${transaction?.transactionID}`, newTransaction);
   195	    }
   196	    return Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION}${transaction?.transactionID}`, newTransaction);
   197	}
