   285	
   286	/**
   287	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   288	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   289	 * is whether the user with that login is typing/leaving on the report or not.
   290	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   291	 *
   292	 * This method makes sure that no matter which we get, we return the "new" format
   293	 */
   294	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   295	    let normalizedStatus: ReportUserIsTyping;
   296	
   297	    if (typingStatus.userLogin) {
   298	        normalizedStatus = {[typingStatus.userLogin]: true};
   299	    } else {
   300	        normalizedStatus = typingStatus;
   301	    }
   302	
   303	    return normalizedStatus;
   304	}
   305	
   306	/** Initialize our pusher subscriptions to listen for someone typing in a report. */
   307	function subscribeToReportTypingEvents(reportID: string) {
   308	    if (!reportID) {
   309	        return;
   310	    }
   311	
   312	    // Make sure we have a clean Typing indicator before subscribing to typing events
   313	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   314	
   315	    const pusherChannelName = getReportChannelName(reportID);
   316	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   317	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   318	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   319	        // since personal details are keyed by accountID.
   320	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   321	        const accountIDOrLogin = Object.keys(normalizedTypingStatus)[0];
   322	
   323	        if (!accountIDOrLogin) {
   324	            return;
   325	        }
   326	
   327	        // Don't show the typing indicator if the user is typing on another platform
   328	        if (Number(accountIDOrLogin) === currentUserAccountID) {
   329	            return;
   330	        }
   331	
   332	        // Use a combo of the reportID and the accountID or login as a key for holding our timers.
   333	        const reportUserIdentifier = `${reportID}-${accountIDOrLogin}`;
   334	        clearTimeout(typingWatchTimers[reportUserIdentifier]);
   335	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, normalizedTypingStatus);
   336	
   337	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   338	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   339	            const typingStoppedStatus: ReportUserIsTyping = {};
   340	            typingStoppedStatus[accountIDOrLogin] = false;
   341	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   342	            delete typingWatchTimers[reportUserIdentifier];
   343	        }, 1500);
   344	    }).catch((error) => {
   345	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   346	    });
   347	}
