   349	/** Initialize our pusher subscriptions to listen for someone leaving a room. */
   350	function subscribeToReportLeavingEvents(reportID: string) {
   351	    if (!reportID) {
   352	        return;
   353	    }
   354	
   355	    // Make sure we have a clean Leaving indicator before subscribing to leaving events
   356	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_LEAVING_ROOM}${reportID}`, false);
   357	
   358	    const pusherChannelName = getReportChannelName(reportID);
   359	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_LEAVING_ROOM, (leavingStatus: Pusher.UserIsLeavingRoomEvent) => {
   360	        // If the pusher message comes from OldDot, we expect the leaving status to be keyed by user
   361	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   362	        // since personal details are keyed by accountID.
   363	        const normalizedLeavingStatus = getNormalizedStatus(leavingStatus);
   364	        const accountIDOrLogin = Object.keys(normalizedLeavingStatus)[0];
   365	
   366	        if (!accountIDOrLogin) {
   367	            return;
   368	        }
   369	
   370	        if (Number(accountIDOrLogin) !== currentUserAccountID) {
   371	            return;
   372	        }
   373	
   374	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_LEAVING_ROOM}${reportID}`, true);
   375	    }).catch((error) => {
   376	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   377	    });
   378	}
